var hfGl = $("gl");
function hfLocal(ev) { var r = $("view3d").getBoundingClientRect();
  return { x: ev.clientX - r.left, y: ev.clientY - r.top }; }
hfGl.addEventListener("pointerdown", function (ev) {
  if (!hf.selectMode) return;
  ev.stopPropagation(); ev.preventDefault();
  hf.drag = { x0: hfLocal(ev).x, y0: hfLocal(ev).y }; hf.drag.x1 = hf.drag.x0; hf.drag.y1 = hf.drag.y0;
  if (controls) controls.enabled = false;
  if (hfGl.setPointerCapture) { try { hfGl.setPointerCapture(ev.pointerId); } catch (e) {} }
}, true);
hfGl.addEventListener("pointermove", function (ev) {
  if (!hf.drag) return;
  ev.stopPropagation();
  var p = hfLocal(ev); hf.drag.x1 = p.x; hf.drag.y1 = p.y;
}, true);
hfGl.addEventListener("pointerup", function (ev) {
  if (!hf.drag) return;
  ev.stopPropagation();
  var p = hfLocal(ev); hf.drag.x1 = p.x; hf.drag.y1 = p.y;
  var drag = hf.drag; hf.drag = null;
  if (controls) controls.enabled = true;
  hfFinishDrag(drag);
}, true);

